"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["8020"],{2271(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>i,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"m13-agentic-capstone/deep-dive","title":"Deep Dive: Agent Internals \u2014 Loops, Dropped Knobs & Constrained Decoding","description":"The core lab had you watch a 0.6B model tool-call, trigger a loop and fix it, and run the whole lifecycle end to end. It showed you that those things happen. This Part 2 explains why, at the level you need to debug them in production: what a loop actually is in terms of the model\'s action space, which spec knobs survive the gateway\'s translation and which get silently eaten, how a JSON schema binds generation rather than just validating it afterward, and the ops notes for what breaks when this runs at scale. The checks live in labs/m13/deep-dive.checks.json.","source":"@site/docs/m13-agentic-capstone/deep-dive.md","sourceDirName":"m13-agentic-capstone","slug":"/m13-agentic-capstone/deep-dive","permalink":"/305-llmops/docs/m13-agentic-capstone/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive: Agent Internals \u2014 Loops, Dropped Knobs & Constrained Decoding","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: Tool-Calling Agents, MCP & the Capstone","permalink":"/305-llmops/docs/m13-agentic-capstone/quiz"}}'),o=n(4848),s=n(8453);let i={sidebar_position:4,title:"Deep Dive: Agent Internals \u2014 Loops, Dropped Knobs & Constrained Decoding",sidebar_label:"Deep Dive (Part 2)"},r="Deep Dive \u2014 Agent Internals: Why Loops Happen, What the Gateway Eats, and How Schemas Bind Generation",l={},h=[{value:"Why loops happen \u2014 the tool schema <em>is</em> the action space",id:"why-loops-happen--the-tool-schema-is-the-action-space",level:2},{value:"The dropped-knob translation \u2014 what LiteLLM forwards and what it eats",id:"the-dropped-knob-translation--what-litellm-forwards-and-what-it-eats",level:2},{value:"How a schema actually binds generation \u2014 constrained decoding",id:"how-a-schema-actually-binds-generation--constrained-decoding",level:2},{value:"Agent evals and sandboxing \u2014 the 303 frontier, named honestly",id:"agent-evals-and-sandboxing--the-303-frontier-named-honestly",level:2},{value:"Capstone ops notes \u2014 what breaks at scale",id:"capstone-ops-notes--what-breaks-at-scale",level:2},{value:"The lineage graph you already built",id:"the-lineage-graph-you-already-built",level:2},{value:"Closing the loop \u2014 a real production failure becomes a golden-set case",id:"closing-the-loop--a-real-production-failure-becomes-a-golden-set-case",level:2},{value:"Where you will use this",id:"where-you-will-use-this",level:2}];function d(e){let t={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"deep-dive--agent-internals-why-loops-happen-what-the-gateway-eats-and-how-schemas-bind-generation",children:"Deep Dive \u2014 Agent Internals: Why Loops Happen, What the Gateway Eats, and How Schemas Bind Generation"})}),"\n",(0,o.jsxs)(t.p,{children:["The core lab had you watch a 0.6B model tool-call, trigger a loop and fix it, and run the whole lifecycle end to end. It showed you ",(0,o.jsx)(t.em,{children:"that"})," those things happen. This Part 2 explains ",(0,o.jsx)(t.em,{children:"why"}),", at the level you need to debug them in production: what a loop actually is in terms of the model's action space, which spec knobs survive the gateway's translation and which get silently eaten, how a JSON schema ",(0,o.jsx)(t.em,{children:"binds"})," generation rather than just validating it afterward, and the ops notes for what breaks when this runs at scale. The checks live in ",(0,o.jsx)(t.code,{children:"labs/m13/deep-dive.checks.json"}),"."]}),"\n",(0,o.jsxs)(t.h2,{id:"why-loops-happen--the-tool-schema-is-the-action-space",children:["Why loops happen \u2014 the tool schema ",(0,o.jsx)(t.em,{children:"is"})," the action space"]}),"\n",(0,o.jsxs)(t.p,{children:["In the lab you left ",(0,o.jsx)(t.code,{children:"tools"}),' in the request on the answer turn and the agent re-called the tool forever. It is tempting to read that as the model being "confused" or "stuck." It is neither. It is the model doing exactly what the request told it it could do.']}),"\n",(0,o.jsxs)(t.p,{children:["On any given turn, the model's legal moves are a function of the request. A plain chat request has one legal move: emit text. A request that carries ",(0,o.jsx)(t.code,{children:"tools"})," has ",(0,o.jsx)(t.em,{children:"two"}),": emit text, or emit a tool call. The tool schemas in the request literally define the ",(0,o.jsx)(t.strong,{children:"action space"})," \u2014 the set of moves available this turn. When you feed a tool result back and ask for the answer ",(0,o.jsx)(t.em,{children:"with the tools still present"}),", you have not changed the action space: calling a tool is still legal, and a model that has any uncertainty about whether it has enough information will often take that move again. Feed ",(0,o.jsx)(t.em,{children:"that"})," result back with tools still present, and again. The loop is not a bug in the model; it is the orchestrator repeatedly offering a move and being surprised the model takes it."]}),"\n",(0,o.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph LOOP["tools present every turn \u2014 the loop"]\n    direction TB\n    L1["turn: action space = {answer, call_tool}"] --\x3e|"model calls tool"| L2["orchestrator runs tool,<br/>feeds result back<br/>WITH tools still present"]\n    L2 --\x3e L1\n  end\n  subgraph FIX["tools omitted on answer turn \u2014 terminates"]\n    direction TB\n    F1["decide turn: action space<br/>= {answer, call_tool}"] --\x3e|"model calls tool"| F2["orchestrator runs tool,<br/>feeds result back<br/>WITH tools OMITTED"]\n    F2 --\x3e F3["answer turn: action space<br/>= {answer}<br/>\u2192 only move is to answer"]\n  end'}),"\n",(0,o.jsxs)(t.p,{children:["This reframes termination correctly: ",(0,o.jsx)(t.strong,{children:"termination is a property of the orchestrator, not the model."}),' The model cannot "decide to stop calling tools" reliably, because as long as the option is on the table, taking it is a valid response to uncertainty \u2014 and small models are ',(0,o.jsx)(t.em,{children:"more"})," uncertain, so ",(0,o.jsx)(t.em,{children:"more"})," loop-prone. The orchestrator terminates the loop by ",(0,o.jsx)(t.strong,{children:"removing the option"}),": omit ",(0,o.jsx)(t.code,{children:"tools"})," on the answer turn and the action space collapses to ",(0,o.jsx)(t.code,{children:"{answer}"}),". There is no move left but to write the response. This is why the fix is one line and why no prompt engineering substitutes for it \u2014 you are not persuading the model, you are changing what is legal."]}),"\n",(0,o.jsxs)(t.p,{children:["Production agents formalize this as a ",(0,o.jsx)(t.strong,{children:"step budget"}),': a hard cap on tool-call rounds (say, 5), after which the orchestrator forces the answer turn regardless of what the model wants. The omit-tools fix is the two-round version of the same principle. The general rule: an agentic loop must have an orchestrator-owned exit condition \u2014 a step count, a tool-omission, a timeout \u2014 because "the model will know when to stop" is not a property you can rely on. (In the lab you saw the loop\'s cost in the spend log; a step budget is what stops that cost from being unbounded.)']}),"\n",(0,o.jsx)(t.h2,{id:"the-dropped-knob-translation--what-litellm-forwards-and-what-it-eats",children:"The dropped-knob translation \u2014 what LiteLLM forwards and what it eats"}),"\n",(0,o.jsxs)(t.p,{children:["The lab's Exhibit B was ",(0,o.jsx)(t.code,{children:'tool_choice: "none"'})," getting silently dropped on the LiteLLM\u2192Ollama path. That is not a one-off quirk; it is the newest member of a family you have been tracking since M2, and the family has a pattern worth naming because it predicts which knobs to distrust."]}),"\n",(0,o.jsxs)(t.p,{children:["Every request that crosses a translation boundary \u2014 your code speaks the OpenAI spec, LiteLLM re-speaks it to Ollama's API, Ollama re-speaks it to the model runtime \u2014 passes through a component that must ",(0,o.jsx)(t.em,{children:"map"})," each parameter to something the next layer understands. A parameter survives only if every layer in the chain knows what to do with it. Three outcomes are possible at each hop:"]}),"\n",(0,o.jsx)(t.mermaid,{value:'flowchart LR\n  P["a spec parameter<br/>(e.g. tool_choice, think, response_format)"] --\x3e H{"does this layer<br/>map it?"}\n  H --\x3e|"forwarded"| OK["honored end to end<br/>(behavior changes)"]\n  H --\x3e|"errored"| ERR["rejected loudly<br/>(you find out immediately)"]\n  H --\x3e|"dropped"| SILENT["silently ignored<br/>(config looks armed,<br/>does nothing)"]'}),"\n",(0,o.jsxs)(t.p,{children:["The dangerous outcome is the third one, because it is invisible. A ",(0,o.jsx)(t.strong,{children:"forwarded"})," knob works. An ",(0,o.jsx)(t.strong,{children:"errored"})," knob tells you it did not work. A ",(0,o.jsx)(t.strong,{children:"dropped"})," knob leaves your config looking armed while it does nothing \u2014 and you only find out by testing behavior. This is the exact same failure class as three earlier exhibits, which is why it is worth seeing as a family rather than a series of unrelated surprises:"]}),"\n",(0,o.jsxs)(t.table,{children:[(0,o.jsx)(t.thead,{children:(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.th,{children:"Module"}),(0,o.jsx)(t.th,{children:"The knob"}),(0,o.jsx)(t.th,{children:"What happened"})]})}),(0,o.jsxs)(t.tbody,{children:[(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"M2"}),(0,o.jsxs)(t.td,{children:[(0,o.jsx)(t.code,{children:"think: false"})," on ",(0,o.jsx)(t.strong,{children:"raw Ollama's"})," ",(0,o.jsx)(t.code,{children:"/v1"})," chat route"]}),(0,o.jsxs)(t.td,{children:["dropped there \u2014 the model kept emitting hidden reasoning tokens, billed but unseen. (Through ",(0,o.jsx)(t.strong,{children:"LiteLLM"})," the same knob ",(0,o.jsx)(t.em,{children:"survives"}),": the gateway forwards ",(0,o.jsx)(t.code,{children:"think"})," to Ollama's native API \u2014 which is why this module's agent can use it on the gateway path. Same knob, two doors, two fates \u2014 that is the family's whole lesson.)"]})]}),(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"M12"}),(0,o.jsxs)(t.td,{children:[(0,o.jsx)(t.code,{children:"prompt_injection_params"})," without the callback"]}),(0,o.jsx)(t.td,{children:"inert \u2014 the params configured a check that was never registered to run"})]}),(0,o.jsxs)(t.tr,{children:[(0,o.jsx)(t.td,{children:"M13"}),(0,o.jsxs)(t.td,{children:[(0,o.jsx)(t.code,{children:'tool_choice: "none"'})," on LiteLLM\u2192Ollama"]}),(0,o.jsx)(t.td,{children:"dropped \u2014 the model kept its full action space and looped"})]})]})]}),"\n",(0,o.jsxs)(t.p,{children:["The through-line: ",(0,o.jsx)(t.strong,{children:"a parameter is a request, not a guarantee."})," The spec defines what you ",(0,o.jsx)(t.em,{children:"may ask for"}),"; whether the ask survives depends on every translation layer between you and the model. The operational discipline that falls out of this is the one the whole course keeps returning to \u2014 ",(0,o.jsx)(t.strong,{children:"verify behavior, not configuration."}),' "I set ',(0,o.jsx)(t.code,{children:"tool_choice: none"}),'" and "tool calls are suppressed" are different claims, and only the second is checked by evidence. When a knob matters for correctness (a loop fix, a guardrail, a cost control), assert it did what you asked with a test that would fail if the knob were dropped \u2014 which is exactly why the lab\'s fix is ',(0,o.jsx)(t.em,{children:"omitting the tools"})," (a structural change the translation cannot drop) rather than ",(0,o.jsx)(t.em,{children:"asking the model not to use them"})," (a knob it can)."]}),"\n",(0,o.jsx)(t.h2,{id:"how-a-schema-actually-binds-generation--constrained-decoding",children:"How a schema actually binds generation \u2014 constrained decoding"}),"\n",(0,o.jsxs)(t.p,{children:['The lesson called structured outputs "the reliability primitive" and said a schema makes the model return valid JSON. That phrasing hides the interesting part: the model does not "try to" return valid JSON and usually succeed. When constrained decoding is in play, invalid JSON is ',(0,o.jsx)(t.em,{children:"impossible to emit"})," \u2014 the schema binds the generation itself."]}),"\n",(0,o.jsxs)(t.p,{children:["Recall how decoding works (M2): at each step the model produces a probability distribution over the whole vocabulary, and the sampler picks the next token from it. ",(0,o.jsx)(t.strong,{children:"Constrained decoding"})," inserts a step between the distribution and the pick: given the schema and the tokens generated so far, it computes which tokens are ",(0,o.jsx)(t.em,{children:"legal next"})," and masks the rest to zero probability before sampling. If the model has emitted ",(0,o.jsx)(t.code,{children:'{"namespace":'})," then the grammar says the next token must open a string value \u2014 so every token that is not a valid continuation is masked out, and the sampler can only pick from what the schema permits."]}),"\n",(0,o.jsx)(t.mermaid,{value:'flowchart LR\n  LOGITS["model\'s next-token<br/>distribution (whole vocab)"] --\x3e MASK["schema grammar:<br/>which tokens are legal<br/>given what\'s emitted so far?"]\n  MASK --\x3e RENORM["mask illegal tokens \u2192 0,<br/>renormalize"]\n  RENORM --\x3e SAMPLE["sample from the<br/>legal tokens only"]\n  SAMPLE --\x3e TOK["next token<br/>(guaranteed schema-valid)"]\n  TOK --\x3e LOGITS'}),"\n",(0,o.jsxs)(t.p,{children:["Two consequences matter operationally. First, ",(0,o.jsx)(t.strong,{children:"the guarantee is structural, not statistical."})," With true constrained decoding you are not hoping the model is well-behaved; malformed output is off the table because the malformed tokens were never selectable. That is what makes structured outputs a ",(0,o.jsx)(t.em,{children:"reliability"})," primitive and not just a prompt trick \u2014 the ",(0,o.jsx)(t.code,{children:"json.loads"})," in your agent loop cannot throw on a syntax error. Second, ",(0,o.jsx)(t.strong,{children:'not every "structured output" path is constrained decoding.'})," Some stacks implement it as prompt-plus-retry (ask for JSON, validate, re-ask on failure) \u2014 which is best-effort and ",(0,o.jsx)(t.em,{children:"can"})," return prose, so your loop still needs a parse-guard. The tool-calling path on most local runtimes (including the Ollama route you used) is grammar-constrained for the ",(0,o.jsx)(t.em,{children:"tool-call structure"})," \u2014 the model cannot emit a malformed tool call \u2014 but the ",(0,o.jsx)(t.em,{children:"arguments"})," inside are constrained only as far as the input schema is expressed as a grammar, which is why arg-hygiene (the ",(0,o.jsx)(t.code,{children:'"pod payments-api"'})," strip) is still your job. Know which kind you have: constrained decoding lets you drop the parse-guard; retry-based structured output does not."]}),"\n",(0,o.jsxs)(t.p,{children:['This is also the mechanistic reason a 0.6B model tool-calls competently. It does not need to be "smart enough to produce valid JSON" \u2014 the decoder ',(0,o.jsx)(t.em,{children:"makes"})," the JSON valid. The model only needs to pick sensible ",(0,o.jsx)(t.em,{children:"values"}),' within the structure the grammar enforces. Capability moves from "can it format correctly" (handled by the constraint) to "does it choose the right tool and arguments" (the model\'s actual job) \u2014 and the lab showed the small model handles the second when the first is guaranteed for it.']}),"\n",(0,o.jsx)(t.h2,{id:"agent-evals-and-sandboxing--the-303-frontier-named-honestly",children:"Agent evals and sandboxing \u2014 the 303 frontier, named honestly"}),"\n",(0,o.jsxs)(t.p,{children:["The lesson pointed past this module to 303-agentops. Two of its topics are worth one paragraph of ",(0,o.jsx)(t.em,{children:"why"})," here, because they are the reason a single read-only agent is a bridge and not the destination."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Agent evals grade trajectories, not answers."})," Every eval in this course graded an ",(0,o.jsx)(t.em,{children:"output"}),": did the answer contain the right runbook, did it refuse the unanswerable question, did it beat the baseline. An agent that takes ",(0,o.jsx)(t.em,{children:"steps"})," needs a different question: was the ",(0,o.jsx)(t.em,{children:"path"})," sensible? An agent can reach a correct answer by luck after five wrong tool calls, or reach a wrong answer through impeccable reasoning \u2014 and an output-only eval scores those identically. Trajectory evals grade the sequence of decisions (did it call the right tool, in a reasonable order, without looping, without wasted steps), which is a strictly harder measurement problem and a whole subfield. Your ",(0,o.jsx)(t.code,{children:"gate.sh"})," measures answers; it is the right tool for a chat assistant and the wrong tool for a multi-step agent."]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Sandboxing is what read-only bought you for free."})," This module's safety came from tool ",(0,o.jsx)(t.em,{children:"design"})," \u2014 the MCP server has no mutating verb, so the agent physically cannot break anything. That is the cheapest possible sandbox: capability-by-absence. The moment an agent's tools ",(0,o.jsx)(t.em,{children:"do"})," mutate the world (restart a deployment, open a PR, run a shell command), absence is no longer available and you need real isolation \u2014 a sandbox that contains the blast radius of a tool the agent ",(0,o.jsx)(t.em,{children:"can"}),' misuse, with its own permission model, resource limits, and audit trail. The visitor-badge discipline scales to "let it look"; it does not scale to "let it act," and the jump between them is exactly what makes agent operations its own course.']}),"\n",(0,o.jsx)(t.h2,{id:"capstone-ops-notes--what-breaks-at-scale",children:"Capstone ops notes \u2014 what breaks at scale"}),"\n",(0,o.jsx)(t.p,{children:"The capstone ran the full lifecycle once, on one machine, at smoke scale. Three things that were invisible at that scale become the operational work at production scale, and naming them is the honest close."}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"The synthesize \u2192 tune \u2192 gate loop is a data pipeline, not a script."})," At smoke scale you ran three commands by hand. At scale, a new runbook landing should ",(0,o.jsx)(t.em,{children:"trigger"})," the pipeline (the Argo Workflow from M11), and the pipeline needs the things every data pipeline needs: idempotency (re-running does not duplicate training data), lineage (which corpus version produced which model version \u2014 the signed kit's digest is your anchor), and a ",(0,o.jsx)(t.strong,{children:"contamination guard"})," that is enforced, not trusted (the synthesizer reading only the corpus and never the golden set must be a checked invariant, because a leak silently inflates the gate score and ships a model that only looks good)."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"The gate's floor is a moving baseline, and moving it is a governance decision."})," The capstone used the committed floor of 8. As the corpus grows and the model improves, that floor should rise \u2014 but ",(0,o.jsx)(t.em,{children:"who"})," raises it, and on ",(0,o.jsx)(t.em,{children:"what evidence"}),", is a policy question, not a config edit. A floor lowered quietly to make a red run green is the single most corrosive thing you can do to an eval gate; it turns the brake into decoration. The floor belongs in version control with a review on every change, so a raise or lower is a visible, defended decision."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"One-take at smoke scale hides the wall-clock."})," The full lifecycle ran in minutes because every heavy step was a smoke profile. A real v1.2 train is hours, a real eval set is larger, and a real promotion touches a cluster serving live traffic. The capstone proves the ",(0,o.jsx)(t.em,{children:"wiring"})," is correct; production adds the concerns the wiring must survive \u2014 training under a resource cap that protects the control plane (the M11 starvation post-mortem), a promotion that drains serving first (one heavyweight at a time), and a rollback that is instant ",(0,o.jsx)(t.em,{children:"because"})," the old bytes never left the PVC. The lifecycle you validated is the skeleton; scale is the load it has to carry."]}),"\n"]}),"\n",(0,o.jsx)(t.h2,{id:"the-lineage-graph-you-already-built",children:"The lineage graph you already built"}),"\n",(0,o.jsx)(t.p,{children:"A chain of custody in an investigation is not one document \u2014 it is the unbroken sequence of\nhandoffs that lets you point at the evidence on the table and prove exactly which steps produced\nit, in order, with nothing swapped in between. You built the LLMOps equivalent across this course\nwithout ever assembling it into one picture. Every stage produced a record that names the stage\nbefore it:"}),"\n",(0,o.jsx)(t.mermaid,{value:'flowchart LR\n  CORPUS["corpus version<br/>(M4 runbooks + Step 1\'s new runbook)"] --\x3e TRAIN["training config<br/>+ base model digest (M6)"]\n  TRAIN --\x3e ADAPTER["adapter / model digest<br/>merged GGUF, v1.2 (M6)"]\n  ADAPTER --\x3e EVALRUN["eval run + score<br/>gate.sh vs golden set (M5/M12)"]\n  EVALRUN --\x3e KIT["signed ModelKit digest<br/>1.2.0 @ sha256:... (M7, cosign)"]\n  KIT --\x3e DEPLOY["deployment commit<br/>opsmate-env PR, Argo sync (M11)"]\n  DEPLOY --\x3e PROD["production traces + feedback<br/>Phoenix, spend log (M10, M13)"]'}),"\n",(0,o.jsxs)(t.p,{children:["Point at any node and you can walk backward to the one before it: the running pod's initContainer\nlog names the ",(0,o.jsx)(t.code,{children:"1.2.0"})," kit it unpacked; the kit's manifest is the digest ",(0,o.jsx)(t.code,{children:"cosign verify"})," checked;\nthe eval report that gated it names the golden set and the floor it cleared; the golden set and\nthe training data both trace to a corpus version. Nothing in that chain is a claim you have to\ntrust \u2014 each link is a file, a digest, or a log line you already captured in this course, and the\ncapstone's ",(0,o.jsx)(t.code,{children:"MODELKIT.md"})," and ",(0,o.jsx)(t.code,{children:"eval-report/"})," are the two links you wrote down by hand."]}),"\n",(0,o.jsxs)(t.p,{children:["This is what an experiment-tracking product like MLflow or Weights & Biases centralizes into one\ndashboard: run metadata, metrics, and artifact lineage in a queryable UI, with comparison views\nacross runs. You have the same graph here, assembled from Git history, a registry, and a signed\ndigest instead of a tracking server \u2014 no worse as evidence, just not queryable in one place. If\nyour team runs many concurrent fine-tunes and needs to compare dozens of runs at a glance, a\ntracking product earns its keep. If you run one lineage at a time and need to ",(0,o.jsx)(t.em,{children:"prove"})," what shipped,\nGit plus a signed digest is the cheaper tool that answers the same question."]}),"\n",(0,o.jsx)(t.h2,{id:"closing-the-loop--a-real-production-failure-becomes-a-golden-set-case",children:"Closing the loop \u2014 a real production failure becomes a golden-set case"}),"\n",(0,o.jsx)(t.p,{children:'The lineage graph above has an arrow at the end \u2014 "production traces + feedback" \u2014 that this\ncourse never actually walked backward from. Software engineering already has the discipline for\nthis: a bug report does not just get fixed, it becomes a regression test, so the same bug can\nnever ship silently again. Nothing in the M5\u2013M12 eval story does that for OpsMate. This section\ncloses it, on a real failure this course\'s own assistant produced.'}),"\n",(0,o.jsx)(t.p,{children:"Ask the live OpsMate assistant a question the corpus genuinely covers:"}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-bash",children:"curl -s \"http://localhost:8001/ask?q=how%20fast%20should%20the%20incident%20commander%20acknowledge%20once%20a%20major%20incident%20is%20declared\" | jq -r '.answer'\n"})}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Expected output"})," (point-in-time; a 0.6B model is not perfectly deterministic run to run, though this one reproduced twice)"]}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-text",children:'The incident commander should acknowledge the major incident within the first\nfifteen minutes. This is explicitly stated in the "Roles and the first fifteen\nminutes" section.\n'})}),"\n",(0,o.jsxs)(t.p,{children:["Read ",(0,o.jsx)(t.code,{children:"major-incident-playbook.md"})," and the answer is wrong, confidently. The runbook's actual\nacknowledgement SLA is ",(0,o.jsx)(t.strong,{children:"ten minutes"}),' ("the rota targets within ten minutes"). "Fifteen minutes"\nis a real number from the same document \u2014 the header of the ',(0,o.jsx)(t.em,{children:"next"}),' section, "Roles and the first\nfifteen minutes," which describes what the commander does once acknowledged, not a deadline for\nacknowledging. The model conflated two real numbers from the same runbook and then cited a\nsection that never states any ack time as its source. Retrieval did its job \u2014 the right runbook\ncame back top-hit \u2014 this is a pure generation-layer error, and it is exactly the dangerous kind:\nit sounds sourced, not invented.']}),"\n",(0,o.jsxs)(t.p,{children:["That is a production failure, captured. Closing the loop means it does not stay a screenshot in a\nchat \u2014 it becomes a new case in ",(0,o.jsx)(t.code,{children:"labs/opsmate/evals/golden.yaml"}),", authored to the file's own\nconvention (a wide ",(0,o.jsx)(t.code,{children:"contains_any"})," net for the right number, a rubric that explicitly fails the\nwrong one and the confabulated citation):"]}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-yaml",children:'  - id: gen-incident-commander-ack\n    layer: generation\n    source: major-incident-playbook.md\n    question: how fast should the incident commander acknowledge once a major incident is declared\n    expect_source: major-incident-playbook.md\n    contains_any:\n      - "ten minutes"\n      - "10 minutes"\n      - "10-minute"\n      - "within ten"\n    rubric: >\n      The answer states the incident-commander rotation targets acknowledgement\n      within ten minutes of declaration. It must NOT say fifteen minutes \u2014 that\n      number belongs to a different fact (the "first fifteen minutes" window of\n      commander actions after roles are filled), not the acknowledgement SLA.\n      Citing the "Roles and the first fifteen minutes" section as the source for an\n      ack-time figure is a confabulated citation and also fails this check.\n'})}),"\n",(0,o.jsxs)(t.p,{children:["Now run the gate with the new case in place \u2014 the same ",(0,o.jsx)(t.code,{children:"gate.sh"})," from the eval-gate wiring\nsection, unchanged, because the whole point of closing the loop through the golden set is that no\npipeline code needs to know a new case exists:"]}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-bash",children:"APP_URL=http://localhost:8001 FLOOR=8 bash labs/m12/eval-gate/gate.sh\n"})}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Expected output"})," (point-in-time; this reference run)"]}),"\n",(0,o.jsx)(t.pre,{children:(0,o.jsx)(t.code,{className:"language-text",children:"OpsMate eval gate \u2014 generation golden set vs the ASSISTANT (http://localhost:8001/ask, retrieval in the path)\nfloor: >= 8 (committed baseline: labs/opsmate/evals/baseline.md)\n----------------------------------------------------------------------\n  PASS  gen-payments-pool\n  PASS  gen-db-failover-find-primary\n  PASS  gen-crashloop-previous-logs\n  fail  gen-disk-reclaim\n  PASS  gen-deploy-rollback-cmd\n  fail  gen-cache-stampede-fix\n  PASS  gen-queue-poison\n  PASS  gen-tls-renew\n  PASS  gen-escalation-sev1\n  PASS  gen-incident-roles\n  fail  gen-incident-commander-ack\n  PASS  gen-backup-drill\n  PASS  gen-vpn-scope\n----------------------------------------------------------------------\ngeneration passed: 10/13   (floor 8)\nVERDICT: PROMOTE \u2014 10 >= 8; the assistant holds the baseline.\n"})}),"\n",(0,o.jsxs)(t.p,{children:["Read this honestly, the way M13's own capstone ops notes taught you to read a gate. ",(0,o.jsx)(t.code,{children:"gen-incident-commander-ack"}),"\nreads ",(0,o.jsx)(t.code,{children:"fail"})," \u2014 the exact failure you just captured is now a named line in the ledger, not a memory.\nThe overall verdict is still ",(0,o.jsx)(t.code,{children:"PROMOTE"}),", and that is ",(0,o.jsx)(t.em,{children:"correct"}),", not a bug in the exercise: ",(0,o.jsx)(t.code,{children:"gate.sh"}),"'s\nfloor is an absolute pass count (10 of 13 clears the floor of 8), not a ratio, so one new failing\ncase does not by itself block a release that was otherwise healthy. What changed is coverage, not\ntoday's verdict \u2014 this exact regression is now catchable on every future run, by name, which it\nwas not five minutes ago. (The two other ",(0,o.jsx)(t.code,{children:"fail"})," lines above, ",(0,o.jsx)(t.code,{children:"gen-disk-reclaim"})," and\n",(0,o.jsx)(t.code,{children:"gen-cache-stampede-fix"}),", are pre-existing \u2014 this assistant's real baseline, not something this\nexercise introduced. Reported here rather than cropped out, because a course that teaches \"verify\nbehavior, not configuration\" does not get to hide its own assistant's warts.)"]}),"\n",(0,o.jsxs)(t.p,{children:["The last step is the one that makes this a ",(0,o.jsx)(t.em,{children:"reviewed"})," addition, not a script silently rewriting\nits own test suite: ",(0,o.jsx)(t.code,{children:"git diff labs/opsmate/evals/golden.yaml"})," is the artifact a human reviews and\napproves before it merges \u2014 the same PR-based promotion discipline M11 already taught, now applied\nto the eval set itself rather than a model version. This course does not wire that PR up for you\nhere (no new required service, the same scoping M10's Deep Dive used for its quality-alert\ndesign) \u2014 but the mechanism is identical to every promotion you have already driven by hand: a\ndiff, a human, a merge, and a gate that runs unchanged on the far side of it."]}),"\n",(0,o.jsx)(t.h2,{id:"where-you-will-use-this",children:"Where you will use this"}),"\n",(0,o.jsxs)(t.p,{children:['The next time an agent you operate spins \u2014 burning tokens, latency climbing, the same tool called over and over \u2014 you will not reach for a prompt tweak. You will look at whether the orchestrator has an exit condition, because you will know the loop is the action space staying open, not the model misbehaving. The next time a spec knob "doesn\'t work," you will test the behavior instead of re-reading the YAML, because you will recognize the dropped-knob family. And the first time you are asked to put an agent into production that can ',(0,o.jsx)(t.em,{children:"act"}),", you will know the two questions that separate a demo from an operation: how is its trajectory evaluated, and what contains it when it is wrong \u2014 the two doors this module deliberately left for the next course to open. And the next time a production failure surfaces \u2014 a wrong answer, a bad tool call, a hallucinated citation \u2014 you will not just fix it and move on; you will ask what golden-set case makes sure it never ships silently again."]})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(6540);let o={},s=a.createContext(o);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);